#!/usr/bin/env python3
"""Build the manual QA index without changing recorded execution results."""
import argparse
import json
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
DIRECTORY = ROOT / 'docs/testing'


def outputs():
    cases = json.loads((DIRECTORY / 'manual-test-cases.json').read_text())['cases']
    assert len({case['id'] for case in cases}) == len(cases), 'Duplicate case ID'
    for case in cases:
        assert (DIRECTORY / case['file']).is_file(), case['id']
        assert case['manual_result'] in ('NOT RUN', 'PASS', 'FAIL', 'BLOCKED'), case['id']
    rows = ['# Zacznij tutaj — ręczny odbiór HARBORLIGHT', '',
        'Każdy wiersz prowadzi do osobnego scenariusza. Wszystkie wyniki startowe to **NOT RUN**. '
        'Zaznaczenie pola oznacza wykonanie i zapisanie wyniku, a nie automatycznie PASS.', '',
        'Najwygodniej otworzyć [interaktywną listę](qa-checklist.html): wynik PASS / FAIL / BLOCKED, '
        'notatki i dowody zapisują się w tej przeglądarce; przyciskiem „Eksportuj raport JSON” pobierz '
        'kopię. Ten plik i jego wyniki są dokumentacją QA, nie zapisem wyspy. '
        'Na GitHub pobierz HTML lub użyj podglądu Pages po jego publikacji; sam widok kodu HTML nie uruchamia listy.', '',
        '1. Wpisz rzeczywisty build/SHA, środowisko, datę i testera. DEV oznacza przestrzeń roboczą/Pages, '
        'PRE-PROD — `harborlight-dev.web.app`; nowy zakres nie jest automatycznie wdrożony w chmurze.',
        '2. Otwórz kartę, przygotuj wskazane dane, wykonaj wszystkie kroki. Brak fixture, usługi, '
        'dostępu albo zatwierdzonej reguły to **BLOCKED** z przyczyną.',
        '3. Zapisz wynik i dowód. Przy FAIL opisz oczekiwane i rzeczywiste zachowanie; dopiero wtedy '
        'powstaje zgłoszenie błędu. Wyniki automatyzacji nie zaliczają testu ręcznego.',
        '4. Eksportuj raport po każdej sesji. Pamięć przeglądarki może zostać usunięta; eksport umożliwia '
        'wznowienie na innym urządzeniu. Raport nie wysyła się automatycznie do Git ani do GCP.', '',
        '**Dane:** używaj profili QA i izolowanej bazy/harnessu. Nie resetuj ani nie podmieniaj historii '
        '`admin1`–`admin3`. Testy przelewów używają symulacji DEV. Integracja planszówki online '
        'pozostaje poza zakresem i ma odrębny BLOCKED; druk i gra przy stole mają własny scenariusz.', '',
        'Pełna metodyka i zależności: [MANUAL-TEST-PLAN.md](MANUAL-TEST-PLAN.md). '
        'Bieżące wydania: [ENVIRONMENT-STATUS.md](../ENVIRONMENT-STATUS.md).', '',
        '## Lista do odhaczania', '']
    for case in cases:
        rows.append('- [ ] [' + case['id'] + ' — ' + case['title'] + '](' + case['file'] + ') · ' +
                    case['priority'] + ' · definicja: **' + case['definition_status'] + '** · wynik: **' +
                    case['manual_result'] + '**')
    rows += ['', '## Wynik pojedynczego przypadku', '',
        '```text', 'Przypadek: HL-TC-…', 'Build/SHA i środowisko:', 'Tester i data:',
        'Fixture/dane:', 'Wynik: PASS / FAIL / BLOCKED', 'Oczekiwane:', 'Uzyskane:',
        'Dowód (zrzut/link/log bez tokenów):', 'Numer błędu, jeśli utworzono:', '```', '',
        '<!-- Generated by scripts/build_manual_checklist.py; canonical cases: manual-test-cases.json. -->', '']
    payload = json.dumps(cases, ensure_ascii=False).replace('<', '\\u003c')
    page = TEMPLATE.replace('__CASES__', payload).replace('__COUNT__', str(len(cases)))
    plan_path = DIRECTORY / 'MANUAL-TEST-PLAN.md'
    plan = plan_path.read_text()
    before, separator, rest = plan.partition('## Indeks\n')
    _, after_separator, after = rest.partition('## Raport i zgłoszenia\n')
    assert separator and after_separator, 'The manual plan is missing its index boundaries'
    table = ['\n| Przypadek | Obszar | Priorytet | Definicja | Wynik ręczny |', '|---|---|---|---|---|']
    table += ['| [' + case['id'] + ' — ' + case['title'] + '](' + case['file'] + ') | ' +
              case['area'] + ' | ' + case['priority'] + ' | ' + case['definition_status'] +
              ' | ' + case['manual_result'] + ' |' for case in cases]
    plan = before + separator + '\n'.join(table) + '\n\n## Raport i zgłoszenia\n' + after
    return {DIRECTORY / 'START-HERE.md': '\n'.join(rows), DIRECTORY / 'qa-checklist.html': page,
            plan_path: plan}


TEMPLATE = '''<!doctype html>
<html lang="pl"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>HARBORLIGHT — ręczny odbiór</title>
<style>
:root{font:16px system-ui,sans-serif;color:#e9f0ed;background:#0d2835;color-scheme:dark}body{max-width:1120px;margin:auto;padding:24px}h1{color:#f4ce7c;margin-bottom:8px}p{line-height:1.55}a{color:#b9ddff}button,input,select,textarea{font:inherit;padding:9px;border:1px solid #64818d;border-radius:8px;background:#173b4b;color:inherit}input,select,textarea{box-sizing:border-box;min-width:0;max-width:100%}.toolbar input{width:100%}button{cursor:pointer}button:hover{background:#245469}label{display:grid;gap:5px}header,.toolbar{display:flex;gap:12px;flex-wrap:wrap;margin:18px 0}.toolbar label{flex:1;min-width:160px}article{border:1px solid #64818d;border-radius:12px;padding:15px;margin:14px 0}article h2{font-size:1.05rem;margin:0 0 8px}article p{margin:7px 0}article textarea{box-sizing:border-box;width:100%;min-height:80px;margin-top:8px}article .fields{display:flex;align-items:center;gap:12px;flex-wrap:wrap}.badge{font-size:.85rem;padding:3px 7px;border-radius:6px;border:1px solid #64818d}.status-PASS{border-left:6px solid #9cce8b}.status-FAIL{border-left:6px solid #ff9890}.status-BLOCKED{border-left:6px solid #f4ce7c}#notice{min-height:24px;color:#f4ce7c}small{color:#c3d1d7}.hidden,[hidden]{display:none!important}@media(max-width:550px){body{padding:14px}header>*{flex:1}}@media print{:root{color:#111;background:white;color-scheme:light}body{max-width:none;padding:0}button,.filters,#notice,#import{display:none!important}input,textarea,select{color:#111;background:white;border-color:#999}article{break-inside:avoid;border-color:#999}a{color:#111}article textarea{min-height:50px}small{color:#333}}
</style>
<h1>HARBORLIGHT — ręczny odbiór</h1>
<p>__COUNT__ osobnych scenariuszy. Wyniki początkowe: <strong>NOT RUN</strong>. PASS oznacza rzeczywiste ręczne wykonanie wszystkich kroków. Brak danych lub usługi oznacz BLOCKED. <a href="MANUAL-TEST-PLAN.md">Plan testów</a> · <a href="../ENVIRONMENT-STATUS.md">Stan środowisk</a>.</p>
<p><small>Wyniki i notatki tej listy są dokumentacją QA zapisywaną w tej przeglądarce, oddzielnie od gry. Lista nie loguje do kont, nie zmienia wysp i nie wysyła raportu do Git/GCP. Eksportuj kopię po każdej sesji; nie umieszczaj tokenów ani danych osobowych w dowodach.</small></p>
<div class="toolbar"><label>Tester<input id="tester" maxlength="120"></label><label>Rzeczywisty build / SHA<input id="build" maxlength="200"></label><label>Środowisko<input id="environment" maxlength="200" placeholder="DEV / PRE-PROD + adres"></label></div>
<header><button id="export">Eksportuj raport JSON</button><button id="load">Wczytaj raport JSON</button><button id="print">Drukuj listę</button><button id="reset">Wyczyść wyniki QA</button><input id="import" type="file" accept="application/json,.json" hidden></header>
<div class="toolbar filters"><label>Szukaj<input id="search" placeholder="ID, nazwa, obszar"></label><label>Wynik<select id="filter"><option value="">Wszystkie</option><option>NOT RUN</option><option>PASS</option><option>FAIL</option><option>BLOCKED</option></select></label></div>
<p id="summary" aria-live="polite"></p><p id="notice" role="status"></p><main id="cases"></main>
<script id="case-data" type="application/json">__CASES__</script>
<script>
'use strict';
const cases=JSON.parse(document.getElementById('case-data').textContent), known=new Set(cases.map(x=>x.id));
const KEY='harborlight-qa-manual-v1', states=['NOT RUN','PASS','FAIL','BLOCKED'];
let report={schema_version:1,tester:'',build:'',environment:'',results:{}};
const byId=id=>document.getElementById(id), notice=text=>{byId('notice').textContent=text;};
function validReport(value){
 if(!value||value.schema_version!==1||typeof value.results!=='object'||Array.isArray(value.results)||value.results===null)throw Error('Nieprawidłowy format raportu.');
 const out={schema_version:1,results:{}};
 for(const key of ['tester','build','environment']){if(typeof value[key]!=='string'||value[key].length>200)throw Error('Nieprawidłowe dane wydania.');out[key]=value[key];}
 for(const [id,item] of Object.entries(value.results)){
  if(!known.has(id))continue;
  if(!item||!states.includes(item.result)||typeof item.notes!=='string'||item.notes.length>5000||typeof item.updated_at!=='string'||item.updated_at.length>80)throw Error('Nieprawidłowy wynik '+id);
  const context={};for(const key of ['tester','build','environment']){const text=item[key]??value[key];if(typeof text!=='string'||text.length>200)throw Error('Nieprawidłowe dane wyniku '+id);context[key]=text;}
  out.results[id]={result:item.result,notes:item.notes,updated_at:item.updated_at,...context};
 }
 return out;
}
try{const saved=localStorage.getItem(KEY);if(saved)report=validReport(JSON.parse(saved));}catch{notice('Pamięć QA jest niedostępna lub nieprawidłowa. Korzystaj z eksportu JSON.');}
function save(){try{localStorage.setItem(KEY,JSON.stringify(report));}catch{notice('Nie udało się zapisać w przeglądarce — wyeksportuj raport JSON.');}}
function statistics(){const counts=Object.fromEntries(states.map(x=>[x,0]));for(const c of cases)counts[report.results[c.id]?.result||'NOT RUN']++;byId('summary').textContent=states.map(x=>x+': '+counts[x]).join(' · ');}
function filter(){const term=byId('search').value.trim().toLocaleLowerCase('pl'),status=byId('filter').value;for(const node of byId('cases').children){const c=cases.find(x=>x.id===node.dataset.caseId);node.hidden=!!(term&&!`${c.id} ${c.title} ${c.area}`.toLocaleLowerCase('pl').includes(term)||status&&(report.results[c.id]?.result||'NOT RUN')!==status);}}
function render(){
 for(const key of ['tester','build','environment'])byId(key).value=report[key];
 byId('cases').replaceChildren();
 for(const c of cases){
  const entry=report.results[c.id]||{result:'NOT RUN',notes:'',updated_at:''},node=document.createElement('article');node.dataset.caseId=c.id;node.className='status-'+entry.result;
  const title=document.createElement('h2'),link=document.createElement('a');link.href=c.file;link.target='_blank';link.rel='noopener';link.textContent=c.id+' — '+c.title;title.append(link);node.append(title);
  const meta=document.createElement('p');meta.textContent=c.priority+' · '+c.area+' · Definicja: '+c.definition_status;node.append(meta);
  const fields=document.createElement('div');fields.className='fields';const label=document.createElement('label');label.textContent='Wynik wykonania';const select=document.createElement('select');select.setAttribute('aria-label','Wynik '+c.id);for(const x of states){const option=document.createElement('option');option.textContent=x;option.selected=x===entry.result;select.append(option);}label.append(select);fields.append(label);const stamp=document.createElement('small');const describe=item=>item.updated_at?'Ostatnia zmiana: '+item.updated_at+' · Build: '+(item.build||'nie wpisano')+' · '+(item.environment||'brak środowiska'):'Nie wykonano';stamp.textContent=describe(entry);fields.append(stamp);node.append(fields);
  const notes=document.createElement('textarea');notes.maxLength=5000;notes.placeholder='Dane/fixture, uzyskany wynik, dowód, przyczyna BLOCKED albo numer błędu';notes.setAttribute('aria-label','Notatki '+c.id);notes.value=entry.notes;node.append(notes);
  const update=()=>{const result={result:select.value,notes:notes.value,updated_at:new Date().toISOString(),tester:report.tester,build:report.build,environment:report.environment};report.results[c.id]=result;node.className='status-'+result.result;stamp.textContent=describe(result);save();statistics();filter();};select.addEventListener('change',update);notes.addEventListener('input',update);byId('cases').append(node);
 }
 statistics();filter();
}
for(const key of ['tester','build','environment'])byId(key).addEventListener('input',()=>{report[key]=byId(key).value;save();});
byId('search').addEventListener('input',filter);byId('filter').addEventListener('change',filter);byId('print').addEventListener('click',()=>window.print());
byId('export').addEventListener('click',()=>{const blob=new Blob([JSON.stringify({...report,exported_at:new Date().toISOString()},null,2)+'\\n'],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='harborlight-qa-'+new Date().toISOString().slice(0,10)+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);notice('Raport pobrany. Zachowaj plik jako kopię i dowód sesji QA.');});
byId('load').addEventListener('click',()=>byId('import').click());byId('import').addEventListener('change',async()=>{const file=byId('import').files[0];try{if(!file||file.size>1000000)throw Error('Wybierz raport JSON do 1 MB.');const next=validReport(JSON.parse(await file.text()));report=next;save();render();notice('Wczytano raport. Nie zmieniono danych gry ani repozytorium.');}catch(error){notice(error.message||'Nie udało się wczytać raportu.');}finally{byId('import').value='';}});
byId('reset').addEventListener('click',()=>{if(!window.confirm('Wyczyścić wyłącznie lokalne wyniki tej listy QA? Najpierw wyeksportuj raport.'))return;report={schema_version:1,tester:'',build:'',environment:'',results:{}};save();render();notice('Wyczyszczono lokalny raport QA. Gra i dane w Git nie zostały zmienione.');});
render();
</script></html>
'''


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--check', action='store_true')
    args = parser.parse_args()
    for path, expected in outputs().items():
        if args.check:
            assert path.is_file() and path.read_text() == expected, str(path) + ' is stale'
        else:
            path.write_text(expected)
    print('Manual checklist ' + ('verified' if args.check else 'built') + '.')


if __name__ == '__main__':
    main()
